def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: int or None, the total number of seconds represented by the timedelta.
    """
    if value is None:
        return None
    try:
        return int(value.total_seconds())
    except Exception:
        return None<|return|>

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    if hasattr(self, "_keys") and isinstance(self._keys, dict):
        return list(self._keys.keys())
    if hasattr(self, "data") and isinstance(self.data, dict):
        return list(self.data.keys())
    if hasattr(self, "content") and isinstance(self.content, dict):
        return list(self.content.keys())
    return list(vars(self).keys())<|return|>

def index(self, key):
    """ Return the index of the given item.
    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except ValueError:
        raise KeyError('Key not found: %s' % key)<|return|>

def values(self, *keys):
    """Return the values of the record, optionally filtering to include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no specific keys or indices are provided, return all values
    if not keys:
        return [value for _, value in self.iteritems()]

    # Collect the requested values
    result = []
    try:
        # Create a list representation of the items to handle indexing
        items_list = list(self.iteritems())
    except AttributeError:
        # Fallback if the object doesn't provide iteritems()
        items_list = list(self.items())

    for k in keys:
        if isinstance(k, int):
            # Treat integers as positional indices
            try:
                result.append(items_list[k][1])
            except IndexError:
                raise IndexError(f"Index {k} is out of range.")
        else:
            # Treat other types as keys
            try:
                result.append(self[k])
            except (LookupError, KeyError):
                # Skip missing keys without raising an exception
                pass
    return result<|return|>

def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass."""
    namespace = {}
    annotations = {}
    for field in fields:
        if isinstance(field, str):
            fname = field
            ftype = 'typing.Any'
        elif isinstance(field, tuple):
            fname = field[0]
            ftype = field[1] if len(field) > 1 else 'typing.Any'
        else:
            raise TypeError(f"Invalid field: {field!r}")
        if fname in annotations:
            raise TypeError(f"Duplicate field name: {fname!r}")
        annotations[fname] = ftype
        # property that reads the attribute from the instance
        namespace[fname] = property(lambda self, _n=fname: getattr(self, _n))
    namespace['__annotations__'] = annotations
    namespace['_srid_map'] = srid_map
    # The base class `Point` is expected to be present in the surrounding
    # context where this factory is used.
    return type(name, (Point,), namespace)<|return|>

def deprecated(message):
    """Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator<|return|>

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Sort the items using a deterministic key based on the characters in each string.
    # This gives a repeatable order for the same input sequence without relying on
    # random number generators or external imports.
    def key_func(item: str) -> int:
        return sum(ord(c) for c in item)

    return [x for _, x in sorted((key_func(x), x) for x in seq)]<|return|>

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    if not s:
        return ()
    parts = [int(p) for p in re.split(r'\D+', s) if p]
    return tuple(parts)<|return|>

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass
                return v
        return _update_wrapper(wrapper, func)
    return decorator<|return|>

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize < 0:
        raise ValueError("'maxsize' must be a non‑negative integer")
    separator = object()

    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            key += (separator,) + tuple(sorted(kwargs.items()))
        if typed:
            key += tuple(type(v) for v in args) + (separator,) + tuple((k, type(v)) for k, v in sorted(kwargs.items()))
        return key

    def decorator(func):
        cache = {}
        order = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                # Move key to end to mark it as most recently used
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            # Evict the most recently used item if we exceed maxsize
            if len(order) > maxsize:
                mru_key = order.pop()  # last element = most recently used
                del cache[mru_key]
            return result

        return wrapper

    return decorator<|return|>

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(fn):
        cache = {}
        freq = {}
        from functools import wraps

        @wraps(fn)
        def wrapper(*args, **kwargs):
            # construct a hashable key; include types if requested
            if typed:
                key = args + tuple((k, type(v)) for k, v in sorted(kwargs.items()))
            else:
                key = args + tuple(sorted(kwargs.items()))

            # cache hit: increment usage frequency and return cached result
            if key in cache:
                freq[key] += 1
                return cache[key]

            # compute result and store in cache
            result = fn(*args, **kwargs)
            cache[key] = result
            freq[key] = freq.get(key, 0) + 1

            # evict least frequently used item if cache exceeds maxsize
            if len(cache) > maxsize:
                min_freq = min(freq.values())
                # Find the first key with the minimum frequency
                for evict_key in list(freq.keys()):
                    if freq[evict_key] == min_freq:
                        cache.pop(evict_key, None)
                        freq.pop(evict_key, None)
                        break

            return result

        return wrapper

    return decorator<|return|>

