def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Base case: no recursion allowed
    if isinstance(level, int) and level == 0:
        return {}
    # Ensure inputs are dict-like
    if d1 is None:
        return {}
    res = {}
    for key, val in d1.items():
        if key not in d2:
            # Key missing in d2, include whole value
            res[key] = val
        else:
            val2 = d2[key]
            # Both values are dictionaries
            if isinstance(val, dict) and isinstance(val2, dict):
                if isinstance(level, int) and level == 1:
                    # At level 1, do not recurse, include val if it differs
                    if val != val2:
                        res[key] = val
                elif isinstance(level, int) and level > 1:
                    subdiff = difference(val, val2, level - 1)
                    if subdiff:
                        res[key] = subdiff
                elif level == -1:
                    subdiff = difference(val, val2, level)
                    if subdiff:
                        res[key] = subdiff
                # If level < 1 (e.g., negative but not infinite), treat as no recursion
                else:
                    pass
            else:
                # Non-dict or differing types, include if values differ
                if val != val2:
                    res[key] = val
    return res<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    result = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recursively process nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, (list, tuple)):
            # Process each element; keep list structure
            processed = []
            for item in value:
                if isinstance(item, dict):
                    processed.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    processed.append(None)
            result[key] = processed
        else:
            # Replace non-dict/list with None
            result[key] = None

    if first_level:
        # Copy identifying fields from the original manifest (if present)
        if 'metadata' in manifest_dict and isinstance(manifest_dict['metadata'], dict):
            md = manifest_dict['metadata']
            meta_copy = {}
            for field in ('name', 'namespace', 'labels', 'annotations'):
                if field in md:
                    meta_copy[field] = md[field]
            result['metadata'] = meta_copy

    return result<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.
    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        import os
        # If path is a pyfs filesystem instance
        if hasattr(path, "exists") and hasattr(path, "open"):
            if not path.isdir("objects"):
                return False
            return True
        # Otherwise assume it's a filesystem path
        if not isinstance(path, (str, bytes, os.PathLike)):
            return False
        if not os.path.isdir(path):
            return False
        if not os.path.isdir(os.path.join(path, "objects")):
            return False
        return True
    except Exception:
        return False<|return|>

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
