def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Ensure we have a dictionary to work with
    if not isinstance(inventory, dict):
        raise ArgumentError("inventory", "Expected a dictionary, got %s" % type(inventory).__name__)

    # Determine which specification version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            match = re.search(r"v(?P<ver>\\d+)", type_val, re.IGNORECASE)
            if match:
                spec_version = match.group("ver")
        elif isinstance(type_val, list):
            # Handle the case where 'type' is a list of values
            for entry in type_val:
                if isinstance(entry, str):
                    match = re.search(r"v(?P<ver>\\d+)", entry, re.IGNORECASE)
                    if match:
                        spec_version = match.group("ver")
                        break

    # Fetch the relevant spec; fall back to the default if not found
    spec = getattr(self, "specs", {}).get(spec_version) or getattr(self, "specs", {}).get(self.spec_version)
    if spec is None:
        raise ArgumentError("inventory", f"Specification for version {spec_version} not found")

    # Validate required keys are present
    required_keys = [k for k, v in spec.items() if v.get("required", False)]
    missing = [k for k in required_keys if k not in inventory]
    if missing:
        raise ArgumentError("inventory", f"Missing required field(s): {', '.join(missing)}")

    # Validate each field present in the inventory against the schema
    for key, value in inventory.items():
        if key not in spec:
            raise ArgumentError("inventory", f"Unexpected field '{key}' for version {spec_version}")

        field_spec = spec[key]
        # Delegated helper to do the actual type/value validation
        self._validate_field(field_spec, value, key)

    return True<|return|>

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise TypeError(f"prior must be an InventoryValidator instance, got {type(prior).__name__}")

        # Compare inventory versions if they exist
        self_version = getattr(self, "inventory_version", None)
        prior_version = getattr(prior, "inventory_version", None)
        if self_version is not None and prior_version is not None:
            if not isinstance(self_version, int) or not isinstance(prior_version, int):
                raise TypeError("inventory_version must be an integer")
            if prior_version >= self_version:
                raise ValueError(
                    f"Prior inventory version ({prior_version}) must be less than current inventory version ({self_version})"
                )

        # Ensure that all species and parameters present in prior are also in current
        for attr in ("species", "parameters"):
            current_set = set(getattr(self, attr, []))
            prior_set = set(getattr(prior, attr, []))
            missing = prior_set - current_set
            if missing:
                raise ValueError(
                    f"Prior {attr} {missing} not found in current inventory's {attr}"
                )

        # Check shapes of stoichiometry matrices (if present)
        if hasattr(self, "stoichiometry_matrix") and hasattr(prior, "stoichiometry_matrix"):
            if self.stoichiometry_matrix.shape != prior.stoichiometry_matrix.shape:
                raise ValueError(
                    f"Stoichiometry matrix shape mismatch: current {self.stoichiometry_matrix.shape} vs prior {prior.stoichiometry_matrix.shape}"
                )

        # Check that number of propensities matches
        if hasattr(self, "propensities") and hasattr(prior, "propensities"):
            if len(self.propensities) != len(prior.propensities):
                raise ValueError(
                    f"Number of propensities differs: current {len(self.propensities)} vs prior {len(prior.propensities)}"
                )
            # Ensure that each prior propensity is a subset of the corresponding current propensity
            for idx, (curr, prev) in enumerate(zip(self.propensities, prior.propensities)):
                # If the expressions differ, check symbol compatibility
                if curr != prev:
                    curr_symbols = set(getattr(curr, "free_symbols", []))
                    prev_symbols = set(getattr(prev, "free_symbols", []))
                    if not prev_symbols.issubset(curr_symbols):
                        raise ValueError(
                            f"Propensity {idx} in prior contains symbols {prev_symbols - curr_symbols} not present in current propensity"
                        )

        # If all checks pass, the prior is considered valid
        return True<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    # helper function to compare versions
    try:
        from packaging.version import Version as _Version
        def _compare(v):
            return _Version(v)
    except Exception:
        # Fallback: simple string comparison
        def _compare(v):
            return v

    # Standardize the target version
    target_version = _compare(version)

    for logical_path, data in inventory.items():
        # Expect data to be either a dict mapping version strings to file sets
        # or directly an iterable of file paths.
        if isinstance(data, dict):
            files_set = set()
            for ver_key, files in data.items():
                # Normalize input files to a set
                if isinstance(files, (set, list, tuple)):
                    files_iter = files
                else:
                    files_iter = {files}
                # Use the version comparison helper
                try:
                    current_version = _compare(ver_key)
                except Exception:
                    current_version = ver_key
                # Include files for the target version and all later ones
                if current_version >= target_version:
                    files_set.update(files_iter)
            logical_path_map[logical_path] = files_set
        else:
            # If data is not a dict, assume it is an iterable of file paths
            if isinstance(data, (set, list, tuple)):
                logical_path_map[logical_path] = set(data)
            else:
                logical_path_map[logical_path] = {data}
    return logical_path_map<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary.")

    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key.")

    files = fixity['files']
    if not isinstance(files, (list, tuple)):
        raise ValueError("'files' entry must be a list or tuple of file names.")

    for f in files:
        if not isinstance(f, str):
            raise ValueError(f"File name '{f}' is not a string.")
        if f not in manifest_files:
            raise ValueError(f"File '{f}' referenced in fixity is not present in the manifest.")

    return True<|return|>

def files_list(path):
    """Return the files in `path`"""
    files = []
    try:
        if isfile(path):
            files.append(abspath(path))
        elif isdir(path):
            for entry in ls(path, abspaths=True):
                if isfile(entry):
                    files.append(entry)
        else:
            raise FileNotFoundError(path)
    except OSError:
        raise FileNotFoundError(path)
    return files<|return|>

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Ensure the file actually exists
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Specified file does not exist: {file_path}")

    # Extract the file name and extension
    base_name = os.path.basename(file_path)
    name, ext = os.path.splitext(base_name)

    # Determine the original file by stripping the language suffix
    suffix = f"-{lang}"
    if name.endswith(suffix):
        original_name = name[: -len(suffix)] + ext
    else:
        raise ValueError(f"File name '{base_name}' does not match the expected pattern '-{lang}'")

    # Initialize the rendition mapping for this instance if needed
    if not hasattr(self, "_renditions"):
        self._renditions = {}
    if original_name not in self._renditions:
        self._renditions[original_name] = {}

    # Store the rendition path
    self._renditions[original_name][lang] = file_path

    # Return the updated mapping for this original file
    return self._renditions[original_name]<|return|>

