def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for info in zin.infolist():
                if info.is_dir():
                    continue
                # Path inside zip
                rel_path = info.filename
                # Get the basename without extension
                base_name = os.path.splitext(os.path.basename(rel_path))[0]
                # Initialize group dict if necessary
                if base_name not in packages:
                    packages[base_name] = {}
                # Read file content
                try:
                    data = zin.read(info)
                except Exception:
                    data = None
                packages[base_name][rel_path] = data
    except Exception:
        # If the zip could not be opened or read, return empty dict
        return {}
    return packages<|return|>

