def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces:
        return ""

    if style is None:
        # Default to plain text
        return " ".join(map(str, pieces))

    # If the style object provides a format method, use it
    if hasattr(style, "format"):
        return style.format(pieces)

    # Simple string identifiers for common styles
    if style == "plain":
        return " ".join(map(str, pieces))
    elif style == "html":
        return "<br>".join(map(str, pieces))
    elif style == "markdown":
        return ", ".join(map(str, pieces))
    else:
        raise ValueError(f"Unsupported style: {style}")<|return|>

