def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.exists(path):
        return f"not found: {path}"
    if os.path.isfile(path):
        name = os.path.basename(path)
        if name.startswith("0="):
            return "file"
        else:
            return f"not a 0= file: {name}"
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except PermissionError:
            return f"permission denied: {path}"
        zero_files = [e for e in entries if e.startswith("0=")]
        if not zero_files:
            return f"no 0=* file found in {path}"
        # Look for a repo-info file to identify a storage root
        if "0=repo-info.json" in zero_files or "0=repo-info.yaml" in zero_files:
            return "root"
        else:
            return "object"
    return f"unknown type for {path}"<|return|>

def amend_bzparams(self, params, bug_ids):
