    # For a single ID pass an integer or string
    if isinstance(bug_ids, (int, str)):
        params['id'] = str(bug_ids)
    # For a list/tuple/set of IDs join them with commas
    elif isinstance(bug_ids, (list, tuple, set)):
        params['ids'] = ','.join(str(bid) for bid in bug_ids)
    else:
