    return params<|return|>

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper for recursive merge of mapping node values
    def _merge_mapping(old_val, new_val):
        # Both are MappingNode and have list of tuples in .value
        merged_children = {}
        child_keys_old = {}
        for k, v in old_val.value:
            key = k.value
            merged_children[key] = (k, v)
            child_keys_old[key] = k
        for k, v in new_val.value:
            key = k.value
            if key in merged_children:
                existing_k, existing_v = merged_children[key]
                # If both values are mappings, merge them recursively
                if isinstance(existing_v, ruamel.yaml.nodes.MappingNode) and isinstance(v, ruamel.yaml.nodes.MappingNode):
                    merged = _merge_mapping(existing_v, v)
                    merged_children[key] = (existing_k, ruamel.yaml.nodes.MappingNode(tag=existing_v.tag, value=merged))
                else:
                    # last wins
                    merged_children[key] = (k, v)
            else:
                merged_children[key] = (k, v)
        # Preserve order from first appearance (which is the order in merged_children dict)
        return [(key_node, val) for key_node, val in merged_children.values()]

    result = {}
    key_nodes = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in result:
            existing_value = result[key]
            # Merge only if both are MappingNode
            if isinstance(existing_value, ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                merged_children = _merge_mapping(existing_value, value_node)
                result[key] = ruamel.yaml.nodes.MappingNode(tag=existing_value.tag, value=merged_children)
            else:
                # last wins
                result[key] = value_node
        else:
            result[key] = value_node
            key_nodes[key] = key_node
    # Build output list preserving the order of first occurrences stored in key_nodes
    merged_list = [(key_nodes[k], result[k]) for k in key_nodes]
    return merged_list<|return|>

