def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping(node):
        """Return True if node is a MappingNode (based on tag)."""
        return hasattr(node, 'tag') and node.tag.endswith('map')

    def merge_mapping_lists(lst1, lst2):
        """Recursively merge two lists of (ScalarNode, Node) pairs representing a mapping."""
        key_map = {}
        # Helper to add or overwrite entries
        def add_entry(key_node, value_node, source):
            """Add or merge an entry into key_map."""
            key = key_node.value
            if key in key_map:
                # Collision: merge values depending on type
                old_key_node, old_value_node = key_map[key]
                if is_mapping(old_value_node) and is_mapping(value_node):
                    # Merge mapping nodes
                    merged_value = MappingNode(
                        tag=value_node.tag,
                        value=merge_mapping_lists(old_value_node.value, value_node.value)
                    )
                    key_map[key] = (old_key_node, merged_value)
                else:
                    # Non-mapping overrides; keep latest value (source's value)
                    # Preserve the key node from the first occurrence
                    key_map[key] = (old_key_node, value_node)
            else:
                # No collision, add directly
                key_map[key] = (key_node, value_node)

        # Process first list, then second to ensure second overrides on collision
        for k, v in lst1:
            add_entry(k, v, source='first')
        for k, v in lst2:
            add_entry(k, v, source='second')
        # Return as list preserving order of first occurrence
        return list(key_map.values())

    merged = {}
    key_order = []

    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            # Merge existing mapping or override with new value
            existing_key_node, existing_value_node = merged[key]
            if is_mapping(existing_value_node) and is_mapping(value_node):
                merged_value = MappingNode(
                    tag=value_node.tag,
                    value=merge_mapping_lists(existing_value_node.value, value_node.value)
                )
                merged[key] = (existing_key_node, merged_value)
            else:
                merged[key] = (existing_key_node, value_node)
        else:
            merged[key] = (key_node, value_node)
            key_order.append(key)

    # Build result list preserving first occurrence order
    result = [merged[k] for k in key_order]
    return result<|return|>

