def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Remove surrounding matching quote characters
    if len(name) > 1 and name[0] == name[-1] and name[0] in ('"', "'", "`"):
        return name[1:-1]
    # Remove any unmatched quote characters
    return name.replace('"', '').replace("'", '').replace("`", '')<|return|>

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Detect platform if needed
    if platform == 'this':
        try:
            import sys
        except ImportError:
            # Fallback: assume POSIX
            platform = 1
        else:
            platform = 0 if sys.platform.startswith('win') else 1

    # Regular expressions for POSIX and Windows/CMD
    posix_re = re.compile(r'''(?:(?:"([^"]*)")|(?:'([^']*)')|([^\s"']+))''')
    windows_re = re.compile(r'''(?:(?:"((?:[^"\\]|\\.)*)")|([^\\\s]+))''')

    if platform:
        pattern = posix_re
    else:
        pattern = windows_re

    parts = []
    for m in pattern.finditer(s):
        # group 1: double-quoted string
        if m.group(1) is not None:
            arg = m.group(1)
        # group 2: single-quoted string (POSIX only)
        elif m.group(2) is not None:
            arg = m.group(2)
        # group 3: unquoted string (WINDOWS)
        else:
            arg = m.group(3)
            # Unescape backslashes and quotes for Windows
            if not platform:
                # Replace escaped characters (e.g., \", \\, \x)
                arg = re.sub(r'\\(.)', r'\1', arg)
        parts.append(arg)

    return parts<|return|>

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    cmd = ['git', 'ls-files', '--others', '--ignored', '--exclude-standard']
    try:
        output = subprocess.check_output(cmd, cwd=ignored, stderr=subprocess.STDOUT)
        files = output.decode('utf-8').splitlines()
        ignored_files = sorted(filter(None, files))
        return ','.join(ignored_files)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.output.decode('utf-8')}")<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == "::1":
                return True
    return False<|return|>

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    # Return None if nothing to convert
    if pattern is None:
        return None
    # If pattern is already a compiled regex, return it
    if isinstance(pattern, re.Pattern):
        return pattern
    # If pattern has a compiled attribute, return it
    if hasattr(pattern, "pattern"):
        return pattern
    # Assume pattern is a string; optionally strip whitespace
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # Unsupported type
    raise TypeError(f"Invalid pattern type: {type(pattern)!r}")<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(args, str):
        args = [args]
    elif args is None:
        args = []

    # Normalize commands to a list
    if isinstance(commands, str):
        commands = [commands]

    results = []
    for cmd in commands:
        # Build the full command
        if isinstance(cmd, str):
            # use shell=True for string commands
            full_cmd = cmd
            if args:
                full_cmd += " " + " ".join(args)
            run_kwargs = {"shell": True}
        else:  # assume iterable of strings
            full_cmd = list(cmd) + list(args)
            run_kwargs = {"shell": False, "args": full_cmd}

        run_kwargs["cwd"] = cwd
        run_kwargs["env"] = env
        run_kwargs["capture_output"] = True
        run_kwargs["text"] = True
        if hide_stderr:
            run_kwargs["stderr"] = subprocess.DEVNULL

        try:
            result = subprocess.run(
                full_cmd,
                **run_kwargs,
                check=True,
            )
        except subprocess.CalledProcessError as exc:
            # propagate the error
            raise

        results.append(result.stdout)
        if verbose:
            print(f"Command run: {full_cmd}")
            print(result.stdout)

    return results<|return|>

