def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""

    # Retrieve request path using common attributes
    path = getattr(request, 'path', None) or getattr(request, 'path_info', None)
    if not path:
        # Fallback to WSGI META if available
        meta = getattr(request, 'META', None)
        if isinstance(meta, dict):
            path = meta.get('PATH_INFO', '')
        else:
            return False

    # Matrix API calls are typically rooted at /_matrix
    if not path.startswith('/_matrix'):
        return False

    # OPTIONAL: Check for JSON payload/accept headers to improve confidence
    meta = getattr(request, 'META', {})
    if isinstance(meta, dict):
        content_type = meta.get('CONTENT_TYPE', '')
        accept = meta.get('HTTP_ACCEPT', '')
        if 'application/json' in content_type.lower() or 'application/json' in accept.lower():
            return True

    # If we reach here, the path itself is enough to classify as a Matrix request
    return True<|return|>

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if dt is None:
        return None
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime instance")
    # If datetime is naive, assume UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    # Convert to UTC and format as ISO 8601 with trailing 'Z'
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                return None
            return resp.headers.get('content-type')
    except Exception:
        return None<|return|>

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str) or not tag:
        return False
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
    for ch in tag:
        if ch not in allowed_chars:
            return False
    return True<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        if key in result:
            # If already a list, just append. If not, make a list.
            if not isinstance(result[key], list):
                result[key] = [result[key]]
            result[key].append(child)
        else:
            result[key] = child
    return result<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("Missing base URL")
    # Base document path for the well-known file
    base = url.rstrip('/') + "/.well-known/nodeinfo"
    # Build the href to the actual NodeInfo document
    if document_path:
        href = url.rstrip('/') + document_path
    else:
        href = f"{base}/1.0"
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/info",
                "type": "application/json",
                "href": href,
            }
        ]
    }<|return|>

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try JSON first
        data = json.loads(document)
        result = {"subject": data.get("subject")}
        for link in data.get("links", []):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                result[rel] = href
        return result
    except Exception:
        pass

    try:
        # Parse XRD (XML)
        root = ElementTree.fromstring(document)
        # Helper to remove namespace
        def strip_ns(tag):
            return tag.split("}")[-1] if "}" in tag else tag
        subject = None
        for elem in root.iter():
            if strip_ns(elem.tag) == "Subject":
                subject = elem.text
                break
        result = {"subject": subject}
        for link in root.findall(".//{*}Link"):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                result[rel] = href
        return result
    except Exception:
        return None
<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        host = handle.split("@")[1]
    except Exception:
        return None
    resource = quote(handle)
    url = f"https://{host}/.well-known/webfinger?resource={resource}"
    try:
        with closing(urllib2.urlopen(url)) as page:
            content = page.read()
            # If we received bytes, decode to string
            if isinstance(content, bytes):
                try:
                    content = content.decode("utf-8", errors="ignore")
                except Exception:
                    return None
            return content
    except Exception:
        return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)<|return|>

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to
    ``requests.request``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    logger.debug(
        "send_document: url=%s, data=%s, timeout=%s, method=%s",
        url, data, timeout, method
    )
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data, "timeout": timeout, "headers": headers
    })
    try:
        response = requests.request(method.upper(), url, *args, **kwargs)
        logger.debug("send_document: response status code %s", response.status_code)
        return response.status_code, None
    except RequestException as ex:
        logger.debug("send_document: exception %s", ex)
        return None, ex<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        file_paths = []
        for directory in settings_dirs:
            for fname in os.listdir(directory):
                if fname.endswith(spec_option):
                    file_paths.append(os.path.join(directory, fname))
        return sorted(file_paths)
    except OSError:
        return []<|return|>

