@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content must be provided")
        try:
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Invalid YAML content: {exc}") from exc
        if data is None or not isinstance(data, dict):
            raise IRValidatorException("Spec content does not contain a YAML mapping")
        required_fields = getattr(cls, "required_fields", [])
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"Missing mandatory field '{field}' in spec")
        return data<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for name, parser in parser_dict.items():
        includes = parser.get('include')
        if not includes:
            continue
        if isinstance(includes, str):
            includes = [includes]
        merged_groups = {}
        for inc_name in includes:
            inc_parser = parser_dict.get(inc_name)
            if not inc_parser:
                continue
            inc_groups = inc_parser.get('groups', {})
            for group_name, group_items in inc_groups.items():
                merged_items = merged_groups.setdefault(group_name, set())
                merged_items.update(group_items)
        # Convert back to list and merge with existing groups
        for gname, items in merged_groups.items():
            existing = parser.get('groups', {}).setdefault(gname, [])
            if not isinstance(existing, list):
                existing = [existing]
                parser['groups'][gname] = existing
            existing.extend(list(items))
        # remove the include directive after processing
        parser.pop('include', None)<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in getattr(self, "spec", []):
        # Use predefined default if available
        if hasattr(arg, "default") and not isinstance(arg.default, NoDefault):
            val = arg.default
        else:
            val = None

        # Check for environment variable override
        env_var = getattr(arg, "env_var", None)
        if env_var:
            import os
            if env_var in os.environ:
                val = os.environ[env_var]

        # Include any other source override logic here
        # (e.g., command‑line or configuration files)

        if val is not None:
            defaults[arg.name] = val

    return defaults<|return|>

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_mapping = getattr(self, 'deprecated_argument_mapping', {})
    for old_arg, new_arg in deprecated_mapping.items():
        cli_has_old = old_arg in cli_args
        file_has_old = old_arg in answer_file_args
        if cli_has_old or file_has_old:
            # Notify the user about deprecation
            print(f"Argument '{old_arg}' is deprecated. Use '{new_arg}' instead.")
            # If the new argument is not already specified, forward the value
            if new_arg not in cli_args and new_arg not in answer_file_args:
                val = cli_args.pop(old_arg, None)
                if val is None:
                    val = answer_file_args.pop(old_arg, None)
                if val is not None:
                    # Prefer CLI over answer file
                    if new_arg in cli_args:
                        cli_args[new_arg] = val
                    else:
                        answer_file_args[new_arg] = val
            else:
                # New argument already present; drop the deprecated one
                cli_args.pop(old_arg, None)
                answer_file_args.pop(old_arg, None)<|return|>

