def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Accept either a dict or an argparse.Namespace (or other object with __dict__)
    if isinstance(args, dict):
        args_dict = args
    elif hasattr(args, '__dict__'):
        args_dict = vars(args)
    else:
        args_dict = {}

    # Consider an argument 'silent' if its value is None or False
    return [name for name, val in args_dict.items() if val in (None, False)]<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the required argument names. This could be defined as a
    # class attribute, instance attribute, or inferred from a function
    # signature. For flexibility, fall back to an empty list if not
    # explicitly provided.
    required = getattr(self, "required_args", getattr(self, "required", []))
    if not required:
        # Nothing to validate
        return

    # Accept both dict-like and sequence arguments
    missing = []
    if isinstance(args, dict):
        for name in required:
            if name not in args or (args[name] is None):
                missing.append(name)
    else:
        # Assume a list/tuple where the order corresponds to required
        # indices. This is a best‑effort guess; raise if sizes don't
        # match.
        if len(args) < len(required):
            missing = required[len(args) :]
        else:
            for i, name in enumerate(required):
                if args[i] is None:
                    missing.append(name)

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []

    # Normalise options_spec to an iterable of (key, option) pairs
    if isinstance(options_spec, dict):
        items = options_spec.items()
    else:
        items = [(opt.get('arg', opt.get('name')), opt) for opt in options_spec]

    for key, opt in items:
        cond = opt.get('required_when')
        if not cond:
            continue

        # The name that should appear in the result
        name = opt.get('arg', key)

        # Determine whether the condition matches
        matched = False
        if callable(cond):
            try:
                matched = bool(cond(args))
            except Exception:
                matched = False
        elif isinstance(cond, str):
            matched = bool(args.get(cond))
        elif isinstance(cond, (list, tuple)):
            matched = all(bool(args.get(item)) for item in cond)
        elif isinstance(cond, dict):
            matched = all(bool(args.get(k)) for k in cond)
        else:
            # Unknown condition type; ignore
            matched = False

        if matched:
            required.append(name)

    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve the argument specifications from the parsed yaml
    argdefs = self.parsed_yaml.get('args', {})
    # Build a list of (name, attrs) tuples from the spec, handling the
    # two possible shapes: dict or list of single‑item dicts.
    if isinstance(argdefs, dict):
        items = argdefs.items()
    else:  # list
        items = []
        for argdict in argdefs:
            # Ensure each list item is a command dict
            self._assert_command_dict(argdict, '[list-item]', ['args'])
            name, attrs = list(argdict.items())[0]
            items.append((name, attrs))

    # For each argument spec, if a maximum length is defined, check it
    for argn, attrs in items:
        maxlen = attrs.get('max_length', attrs.get('len'))
        if maxlen is None:
            continue
        if not isinstance(maxlen, (int, float)):
            raise TypeError(f"Maximum length for argument '{argn}' must be a number, got {type(maxlen).__name__}")
        if maxlen < 0:
            raise ValueError(f"Maximum length for argument '{argn}' must be non‑negative, got {maxlen}")

        if argn not in args:
            continue
        value = args[argn]
        try:
            l = len(value)
        except Exception:
            raise ValueError(f"Argument '{argn}' has no length; cannot validate against maximum length")

        if l > maxlen:
            raise ValueError(f"Argument '{argn}' length ({l}) exceeds allowed maximum ({maxlen})")<|return|>

def validate_choices_args(self, args):
        """
        Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Retrieve argument definitions from parsed YAML
        arg_defs = self.parsed_yaml.get('args', {})
        # Helper to map list items to dict of name->attrs
        def _list_to_map(item_list):
            mapping = {}
            for item in item_list:
                # item is a dict with a single key/value pair
                key, attrs = list(item.items())[0]
                mapping[key] = attrs
            return mapping

        # Build a lookup table of argument attributes
        if isinstance(arg_defs, dict):
            arg_attrs_map = arg_defs
        else:  # list of dicts
            arg_attrs_map = _list_to_map(arg_defs)

        # Validate each provided argument against its choices (if any)
        for arg_name, value in args.items():
            attrs = arg_attrs_map.get(arg_name)
            if not attrs:
                continue  # unknown argument – may be caught elsewhere
            choices = attrs.get('choices')
            if choices is not None:
                if value not in choices:
                    abort(
                        "Invalid choice for argument '{}': '{}'. "
                        "Valid options: {}".format(arg_name, value, choices)
                    )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.
    :param args: The received arguments.
    """
    # Expect args to be a mapping (dict) where each key is the argument name
    # and the value is a mapping/dict containing 'value', 'min', and 'max'.
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping of argument names to properties")
    for arg_name, props in args.items():
        if not isinstance(props, dict):
            raise TypeError(f"Properties for argument '{arg_name}' must be a dict")
        # Ensure required keys exist
        for key in ('value', 'min', 'max'):
            if key not in props:
                raise ValueError(f"Argument '{arg_name}' missing required key '{key}'")
        val = props['value']
        min_val = props['min']
        max_val = props['max']
        # Validate that min <= max
        if min_val > max_val:
            raise ValueError(f"Argument '{arg_name}': min ({min_val}) is greater than max ({max_val})")
        # Validate value lies within range
        if not (min_val <= val <= max_val):
            raise ValueError(
                f"Argument '{arg_name}': value {val} is out of range [{min_val}, {max_val}]")
    return args<|return|>

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if vars_dict is None:
        vars_dict = {}
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, dict):
        extra_mapping = extra_vars
    elif isinstance(extra_vars, list):
        extra_mapping = {}
        for entry in extra_vars:
            if isinstance(entry, dict):
                extra_mapping.update(entry)
    else:
        raise TypeError("extra_vars must be a list or dict")
    vars_dict.update(extra_mapping)
    return vars_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Mapping of known types per parser and argument name
    type_map = {}
    if parser_name == "main":
        type_map = {"port": int, "debug": bool, "timeout": float}
    elif parser_name == "virsh":
        type_map = {"memory": int, "cores": int}
    elif parser_name == "ospd":
        type_map = {"quiet": bool, "threads": int}

    for key, value in list(values_dict.items()):
        target_type = type_map.get(key)
        if target_type:
            try:
                if target_type is bool:
                    if isinstance(value, str):
                        values_dict[key] = value.lower() in ("true", "1", "yes", "y", "on")
                    else:
                        values_dict[key] = bool(value)
                else:
                    values_dict[key] = target_type(value)
            except Exception:
                pass
        else:
            # Heuristic conversion for unknown keys
            if isinstance(value, str):
                v = value.strip()
                # int
                if v.isdigit():
                    values_dict[key] = int(v)
                else:
                    # float
                    try:
                        values_dict[key] = float(v)
                    except ValueError:
                        # bool
                        if v.lower() in ("true", "false"):
                            values_dict[key] = v.lower() == "true"
                # otherwise keep string

    return values_dict<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine the spec file (JSON or YAML)
    spec_file = None
    for ext in ("json", "yaml", "yml"):
        path = os.path.join(plugin_dir, f"spec.{ext}")
        if os.path.isfile(path):
            spec_file = path
            break

    if spec_file is None:
        raise FileNotFoundError(f"No spec.json/yaml found in {plugin_dir}")

    # Load spec (JSON support; YAML can be added if needed)
    with open(spec_file, "r", encoding="utf-8") as f:
        if spec_file.endswith(".json"):
            spec = json.load(f)
        else:
            # Fallback: try YAML (requires PyYAML)
            try:
                import yaml  # type: ignore
                spec = yaml.safe_load(f)
            except Exception as e:
                raise ValueError(f"Unable to parse {spec_file}: {e}")

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    key = f"{new_key}[{i}]"
                    if isinstance(item, dict):
                        items.update(_flatten(item, key, sep=sep))
                    else:
                        items[key] = item
            else:
                items[new_key] = v
        return items

    return _flatten(spec)<|return|>

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    if env_var not in os.environ:
        os.environ[env_var] = str(self.config_path)<|return|>
